#!/usr/bin/env python3
"""Compare stored raw result bytes, including bytes after NUL, and persist JSON replacement results and observe subtype erasure on storage and failures in both public Core file engines.

Pinned C supplies page geometry and input JSONB/JSON text. Newly seeded data and SQL
variants mix with fixed transaction/INSERT/UPDATE/DELETE/RETURNING/CTAS
templates. Each statement is delivered on its own input line so the pinned C
CLI honors -bail at the same boundary; the original template is also retained.
Same-line CLI continuation is documented separately. Compare full stdout, normalized first-line error, post-statement
C typed rows/schema shape/integrity, Lean reopen, and a subsequent independent C
write. Preserve unchanged files when C leaves its input unchanged. Page size
is recorded separately because the current writer may convert it to 4096.
"""
import argparse,hashlib,json,os,random,re,shutil,subprocess,tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def digest():
 h=hashlib.sha256()
 for p in sorted((ROOT/'SQLeanite').rglob('*.lean'))+[ROOT/'Main.lean']:h.update(str(p.relative_to(ROOT)).encode()+b'\0'+p.read_bytes())
 return h.hexdigest()
def literal(s):
 data=s.encode() if isinstance(s,str) else s
 return "CAST(X'"+data.hex()+"' AS TEXT)"
def statement_lines(sql):
 """Keep SQL tokens intact; put the next statement on a new CLI input line."""
 out=[];quote=None;i=0
 while i<len(sql):
  char=sql[i]
  if quote is not None:
   out.append(char)
   if char==quote:
    if quote!=']' and i+1<len(sql) and sql[i+1]==quote:
     out.append(sql[i+1]);i+=2;continue
    quote=None
   i+=1;continue
  if sql.startswith('--',i):
   end=sql.find('\n',i)
   if end<0:out.append(sql[i:]);break
   out.append(sql[i:end+1]);i=end+1;continue
  if sql.startswith('/*',i):
   end=sql.find('*/',i+2)
   if end<0:out.append(sql[i:]);break
   out.append(sql[i:end+2]);i=end+2;continue
  if char in "'\"`[":quote=']' if char=='[' else char
  out.append(char)
  if char==';':out.append('\n')
  i+=1
 return ''.join(out)

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--seed',type=int,default=355292);p.add_argument('--fixtures',type=int,default=4);p.add_argument('--random-cases',type=int,default=16);p.add_argument('--output',type=Path,required=True);a=p.parse_args();rng=random.Random(a.seed)
 sqlite=os.environ.get('SQLITE3_BIN','sqlite3');binary=ROOT/'.lake/build/bin/sqleanite';source=digest();exe=hashlib.sha256(binary.read_bytes()).hexdigest()
 def run(cmd,sql):
  r=subprocess.run(cmd,input=sql.encode(),capture_output=True,timeout=120)
  return dict(code=r.returncode,stdout=r.stdout.decode('latin1'),stderr=r.stderr.decode('latin1'))
 def csql(path,sql):return run([sqlite,'-batch','-bail',str(path)],sql)
 def error(r):
  if not r['code']:return ''
  line=r['stderr'].splitlines()[0] if r['stderr'] else ''
  return re.sub(r'^(?:Parse error|Runtime error|Error)(?: near line [0-9]+)?: ?', '',line)
 def snapshot(path):
  return {s:hashlib.sha256(Path(str(path)+s).read_bytes()).hexdigest() for s in ['','-wal'] if Path(str(path)+s).exists()}
 def same(l,r):return bool(l['code'])==bool(r['code']) and l['stdout']==r['stdout'] and error(l)==error(r)
 inputs=[literal(s) for s in ['null','1','[]','{"a":[1,true]}','{a:1}','[1,]','"\\x41"','invalid','[','01','1\0junk']]
 inputs += ['NULL','1','1.25',"X'00'","X'0b'","X'3c176100'","X'1bff'","X'c000'","X'00ff'"]
 inputs += [literal('"a\\u0000b"'),literal('"\\u0000tail"'),"X'3a610062'","X'37ff007a'"]
 generated=[]
 for _ in range(a.random_cases):
  value={'v':[rng.randrange(-100000,100000),rng.choice([None,True,False]),''.join(rng.choice('abé中😀') for _ in range(5))]}
  s=json.dumps(value,ensure_ascii=False);r=csql(':memory:','SELECT hex(jsonb('+literal(s)+'));');assert r['code']==0,r
  generated.append(dict(text=s,jsonb_hex=r['stdout'].strip()))
  inputs.extend([literal(s),"X'"+r['stdout'].strip()+"'"])
 scripts=[]
 def add(group,sql):scripts.append(dict(group=group,template_sql=sql,sql=statement_lines(sql)))
 expressions=["json_replace(v,flags,'new')","jsonb_replace(v,flags,'new')","json_replace(v,flags,json('{}'))","jsonb_replace(v,flags,jsonb('{}'))","json_replace(v,'$',v)","jsonb_replace(v,'$',v)","json_replace(v,'$',json_array(v))","json_array(json_replace(v,'$',json('{}')))"]
 for expr in expressions:
  for where in ['', ' WHERE id<=7', ' WHERE id>21', ' WHERE 0']:
   add('update',f'UPDATE t SET valid={expr}'+where+' RETURNING id,typeof(valid),subtype(valid),hex(valid),hex(quote(valid));')
   add('insert-select',f'INSERT INTO out SELECT id,{expr} FROM t'+where+';')
   add('ctas',f'CREATE TABLE made AS SELECT id,{expr} AS valid FROM t'+where+';')
  add('delete',f'DELETE FROM t WHERE {expr}>0 RETURNING id;')
 for suffix in ['ROLLBACK;','COMMIT;']:
  add('transaction',"BEGIN; UPDATE t SET valid=json_replace(v,'$',json('{}')) WHERE id<=7; "+suffix+' SELECT id,typeof(valid),hex(valid) FROM t ORDER BY id;')
 add('savepoint',"SAVEPOINT j; UPDATE t SET valid=jsonb_replace(v,'$',jsonb('{}')) WHERE id<=7; ROLLBACK TO j; RELEASE j; SELECT id,hex(valid) FROM t ORDER BY id;")
 error_expr="json_replace(v,flags,CASE WHEN id=3 THEN abs(-9223372036854775808) ELSE v END)"
 for sql in ['UPDATE t SET valid='+error_expr+';', 'INSERT INTO out SELECT id,'+error_expr+' FROM t;', 'CREATE TABLE made AS SELECT id,'+error_expr+' AS valid FROM t;', 'UPDATE t SET valid=1 WHERE id<=7 RETURNING id,'+error_expr+';']:
  add('atomic-error',sql)
 for fn in ['json_replace','jsonb_replace']:
  for args in ['', '*',"'{}'","'{}','$'","NULL,'bad'","'{}',NULL,X'ff'","'{}','$[bad]',X'ff'","'{}','bad',X'ff'"]:
   for where in ['', ' WHERE 0']:add('call-shape','UPDATE t SET valid='+fn+'('+args+')'+where+';')
  add('argument-limit','UPDATE t SET valid='+fn+'('+','.join(['1']*1001)+') WHERE 0;')
  for args in ["'$.a',1,'$.a',2","'$.b',json('[9]'),'$.b[0]',8","'$',NULL,'$',1","'$[0]',NULL,'$[2]',json('{}')"]:
   add('sequential-replacement',"UPDATE t SET valid="+fn+"('{a:1,b:[2,3],a:4}',"+args+') WHERE id<=7 RETURNING id,hex(valid);')
  call=fn+"(json_group_object(flags,v),'$',json_group_array(v))"
  add('aggregate-source','INSERT INTO out SELECT id%3,'+call+' FROM t WHERE id<=7 GROUP BY id%3;')
  add('aggregate-source','CREATE TABLE made AS SELECT id%3 AS id,'+call+' AS valid FROM t WHERE id<=7 GROUP BY id%3;')
 for expr in ["json_replace('{}','$',1)","json_replace('{}','$',json('{}'))","jsonb_replace('{}','$',json('{}'))","json_replace('{}','$',NULL)"]:
  for insert_source in ['VALUES(998,'+expr+')','VALUES(998,'+expr+'),(999,'+expr+')','SELECT 998,'+expr]:
   add('insert-returning-subtype','INSERT INTO out '+insert_source+' RETURNING id,typeof(valid),subtype(valid),hex(valid); SELECT id,subtype(valid),hex(valid) FROM out ORDER BY id;')
  for affinity in ['', 'BLOB','TEXT','INT','REAL','NUMERIC']:
   for auto in ['', 'AUTOINCREMENT']:
    setup="CREATE TABLE made(id INTEGER PRIMARY KEY "+auto+",valid "+affinity+" NOT NULL ON CONFLICT REPLACE DEFAULT ("+expr+"));"
    for mutation in ["INSERT INTO made DEFAULT VALUES", "INSERT INTO made(id) VALUES(1),(2)","INSERT INTO made VALUES(1,NULL)"]:
     add('default-returning-subtype',setup+mutation+' RETURNING id,typeof(valid),subtype(valid),hex(valid);SELECT id,subtype(valid),hex(valid) FROM made ORDER BY id;')
 for _ in range(a.random_cases):
  fn=rng.choice(['json_replace','jsonb_replace']);value=rng.choice(['v','json(v)',"json('{}')","jsonb('{}')",'NULL',"X'ff'",'flags']);path=rng.choice(["'$'","'$.v'",'flags','NULL']);lo=rng.randrange(len(inputs)+1);hi=lo+rng.randrange(1,10)
  add('seeded-replacement-update',f'UPDATE t SET valid={fn}(v,{path},{value}) WHERE id BETWEEN {lo} AND {hi} RETURNING id,subtype(valid),hex(valid);')
